import { NgTemplateOutlet } from '@angular/common';
import {
  ChangeDetectionStrategy,
  Component,
  computed,
  inject,
  input,
  output,
} from '@angular/core';
import { RouterLink } from '@angular/router';
import { CampaignOverview } from '../../../_models/campaign';
import { RoutingService } from '../../../_services/routing.service';
import { FeatureService } from '../../../_services/utils/feature.service';
import { ButtonLinkComponent } from '../../atoms/button-link/button-link.component';
import { ButtonComponent } from '../../atoms/button/button.component';
import { IconComponent } from '../../atoms/icon/icon.component';
import { SpinnerComponent } from '../../atoms/spinner/spinner.component';
import {
  ImageGridComponent,
  ImageGridEntry,
} from '../../organisms/image-grid/image-grid.component';

@Component({
  selector: 'app-campaign-overview',
  templateUrl: './campaign-overview.component.html',
  styleUrls: ['./campaign-overview.component.scss'],
  imports: [
    NgTemplateOutlet,
    ButtonComponent,
    RouterLink,
    ImageGridComponent,
    SpinnerComponent,
    ButtonLinkComponent,
    IconComponent,
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CampaignOverviewComponent {
  readonly serverUrl = input.required<string>();
  readonly userName = input.required<string | undefined>();
  readonly campaigns = input.required<CampaignOverview[] | undefined>();
  readonly isGlobalAdmin = input(false);

  readonly logout = output<void>();

  private readonly features$ = inject(FeatureService).features$;
  readonly enableCampaignCreation = computed(
    () =>
      !this.features$.isLoading() &&
      this.features$.value()?.enablePublicCampaignCreation,
  );
  readonly campaignCreateUrl =
    this.routingService.getRoutePath('campaign-create');

  readonly profileUrl = computed(() =>
    this.routingService.getRoutePath('direct-profile', {
      username: this.userName(),
    }),
  );
  readonly configTableUrl = computed(() =>
    this.routingService.getRoutePath('config-tables'),
  );
  readonly generalAdminUrl = computed(() =>
    this.routingService.getRoutePath('admin'),
  );
  readonly gridEntries = computed<ImageGridEntry[] | undefined>(() =>
    this.campaigns()?.map((campaign) => ({
      imageUrl: campaign.background_image,
      label: campaign.name,
      icon: campaign.icon,
      link: this.routingService.getRoutePath('home', {
        campaign: campaign.name,
      }),
      ariaLabel: `Look at campaign ${campaign.name}`,
    })),
  );
  readonly dragonFrameUrl = 'assets/general_overview.webp';

  constructor(private routingService: RoutingService) {}
}
